command:
$ErrorActionPreference='Stop'; [Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
$top=Get-WinEvent -LogName System -MaxEvents 1
$os=Get-CimInstance Win32_OperatingSystem
$events=@()
if (353588 -ge 0) {
  $xpath="*[System[(EventRecordID > 353588 and EventRecordID <= $($top.RecordId)) and ((Provider[@Name='Microsoft-Windows-Kernel-Power'] and (EventID=42 or EventID=506 or EventID=107 or EventID=507)) or (Provider[@Name='Microsoft-Windows-Power-Troubleshooter'] and EventID=1))]]"
  $events=@(Get-WinEvent -LogName System -FilterXPath $xpath -ErrorAction SilentlyContinue | Sort-Object RecordId | ForEach-Object {
    [ordered]@{record_id=[int64]$_.RecordId;event_id=$_.Id;provider=$_.ProviderName;time_utc=$_.TimeCreated.ToUniversalTime().ToString('o');message=$_.Message;xml=$_.ToXml()}
  })
  if ($Error.Count -gt 0 -and $Error[0].FullyQualifiedErrorId -notlike 'NoMatchingEventsFound*') { throw $Error[0] }
}
[ordered]@{schema='raw-comparison-power-events-v1';log='System';cursor_before=353588;cursor_after=[int64]$top.RecordId;windows_boot_utc=$os.LastBootUpTime.ToUniversalTime().ToString('o');events=$events;at=[DateTimeOffset]::Now.ToString('o')} | ConvertTo-Json -Depth 8
